!STORY_HOOK_FRIEZA_VICTORY          = frieza_h_victory
!STORY_HOOK_FRIEZA_DEFEATED         = frieza_h_defeated
!STORY_HOOK_FRIEZA_REVIVE           = frieza_h_revive
!STORY_HOOK_FRIEZA_REPAIR_CORE      = frieza_h_repair_core
!STORY_HOOK_BEAST_CHOOSE_ORDINARY   = frieza_h_beast_ordinary
!STORY_HOOK_BEAST_CHOOSE_FEED       = frieza_h_beast_feed
!STORY_HOOK_BEAST_VICTORY           = frieza_h_beast_victory
!STORY_HOOK_OBJECT_FRIEZA           = frieza_h_object
!STORY_QUERY_FRIEZA_CRISIS          = frieza_q_crisis
!STORY_QUERY_FRIEZA_STOLEN          = frieza_q_stolen
!STORY_QUERY_FRIEZA_PENDING         = frieza_q_pending
!STORY_QUERY_FRIEZA_PALACE          = frieza_q_palace
!STORY_QUERY_FRIEZA_NEEDS_TREE      = frieza_q_needs_tree
!STORY_QUERY_FRIEZA_ELIGIBLE        = frieza_q_eligible
