endif

; Combat: Goku's damage to the Beast and the empowered Dark Lich
; (beast-challenge.js damage()), bound by combat's bind.asm when present.
!COMBAT_HOOK_DAMAGE = frieza_combat_damage

; Debug scene select: restore Frieza / Beast state for the presets.
incsrc "debug/defines.asm"
; (Test builds -DDEBUG_TEST log every call through debug's own ANY hook;
; frieza_debug_preset_test logs through it first, so Frieza's restores still
; decide the story routes the presets take.)
if defined("DEBUG_TEST")
!DEBUG_PRESET_HOOK_ANY = frieza_debug_preset_test
else
!DEBUG_PRESET_HOOK_ANY = frieza_debug_preset
endif
!FZ_PAYLOAD #= !DEBUG_PAYLOAD_BANK<<16

; ---------------------------------------------------------------------------
pushpc
org !DATA_FRIEZA
frieza_data_start:
incsrc "frieza/data.asm"
frieza_data_end:
assert frieza_data_end <= !DATA_FRIEZA+$8000, "frieza data bank overflow"
pullpc

pushpc
org !FRIEZA_ART_BANK<<16
frieza_art:
incbin "frieza/art.bin"
frieza_art_end:
assert frieza_art_end <= (!FRIEZA_ART_BANK<<16)+$8000, "frieza art overflow"
pullpc

; ---------------------------------------------------------------------------
; Original code patched (asserted).
; Door table read (C1:E7F2 LDA $C83002,X): door 3FC's entry while the
; Emperor is present (native-story.js storyRead of C8:3FF2).
%orig4($C1E7F2, $C83002BF)
%hijack_jsl($C1E7F2, frieza_door_entry, 4, frieza)

pushpc
org !CODE_FRIEZA
frieza_code_start:
incsrc "frame.asm"
incsrc "state.asm"
incsrc "scene.asm"
incsrc "sprite.asm"
incsrc "battle.asm"
incsrc "beast.asm"
frieza_code_end:
assert frieza_code_end <= !CODE_FRIEZA+$7000, "frieza code bank overflow"
pullpc
